_family = CubinFamily("gated_delta")
_ENABLE_JIT = is_cute_jit_enabled()

_CONV_KERNEL_SIZE = 4
_DEFAULT_VALUE_HEADS = 16
_RECURRENT_HEAD_DIM = 128
_THREADS = 256
_PACKED_CONV_CHANNEL_TILE = 64
_PACKED_CONV_SEQ_TILE = 64
_PACKED_CONV_THREADS = 128
_PREFILL_PREP_WARPS_PER_BLOCK = 8
_GATED_RMSNORM_WARPS_PER_BLOCK = 8
_REPLAY_CAPACITIES = (1, 2, 4, 8, 16)
_REPLAY_DECODE_THREADS = 128
_REPLAY_DECODE_VALUE_TILE = 64
_REPLAY_ADVANCE_THREADS = 128
_REPLAY_MATERIALIZE_THREADS = 128
_REPLAY_MATERIALIZE_VALUE_TILE = 64
_TENSORMAP_WORKSPACE_CACHE: dict[tuple[int, int], torch.Tensor] = {}
_SM100_TENSORMAP_WORKSPACE_CACHE: dict[tuple[int, int], torch.Tensor] = {}

if _ENABLE_JIT:
    from scripts.precompile import cubin_bundles as _cubin_bundles


@lru_cache(maxsize=None)
def supports_packed_gdn(
    device: torch.device | str,
    dtype: torch.dtype,
    num_k_heads: int,
    num_v_heads: int,
    head_dim: int,
) -> bool:
    """Return whether the CUDA GDN family has native packed variants."""

    demand = packed_gated_delta_demand(
        dtype,
        num_k_heads,
        num_v_heads,
        head_dim,
    )
    return PACKED_GATED_DELTA_PROVIDER.supports_semantics(
        demand,
        backend=torch.device(device).type,
    )


# Fully-fused (chunked) SM90 delta-rule prefill, dispatched through AOT-emitted
# host wrappers. The equal-head key is kept stable for the existing artifact;
# GQA shapes use separate keys so the non-GQA path does not pick up extra
# runtime work.
def _recurrent_variant_key(op: str, num_k_heads: int, num_v_heads: int, head_dim: int) -> str:
    if num_k_heads == num_v_heads:
        return f"{op}_bf16_h{num_k_heads}_d{head_dim}"
    return f"{op}_bf16_k{num_k_heads}_v{num_v_heads}_d{head_dim}"


def _replay_variant_key(
    num_k_heads: int,
    num_v_heads: int,
    head_dim: int,
    capacity: int,
) -> str:
    return f"{_recurrent_variant_key('replay_decode_indexed', num_k_heads, num_v_heads, head_dim)}_c{capacity}"


def _flat_sm90_variant_key(
    num_k_heads: int,
    num_v_heads: int,
    head_dim: int,
) -> str:
    return _recurrent_variant_key("flat_prefill_sm90", num_k_heads, num_v_heads, head_dim)


def _flat_sm90_indexed_state_variant_key(
    num_k_heads: int,
    num_v_heads: int,
    head_dim: int,
) -> str:
    return _recurrent_variant_key(
        "flat_prefill_sm90_indexed_state", num_k_heads, num_v_heads, head_dim
    )


def _chunk_sm100_indexed_state_variant_key(
    num_k_heads: int,
    num_v_heads: int,
    head_dim: int,
) -> str:
    return _recurrent_variant_key(
        "chunk_prefill_sm100_indexed_state", num_k_heads, num_v_heads, head_dim
    )


def _infer_gqa_shape_from_mixed(
    mixed_dim: int,
    num_v_heads: int,
    head_dim: int = _RECURRENT_HEAD_DIM,
) -> tuple[int, int, int] | None:
    if num_v_heads <= 0:
        return None
    value_dim = num_v_heads * head_dim
    qk_packed_dim = mixed_dim - value_dim
    if qk_packed_dim <= 0 or qk_packed_dim % (2 * head_dim) != 0:
        return None
    num_k_heads = qk_packed_dim // (2 * head_dim)
    if num_k_heads <= 0 or num_v_heads % num_k_heads != 0:
        return None
    return (num_k_heads, num_v_heads, head_dim)


def _compile_flat_sm90_variant(variant_key: str):
    for num_k_heads, num_v_heads, head_dim in _SUPPORTED_RECURRENT_SHAPES:
        if variant_key == _flat_sm90_variant_key(num_k_heads, num_v_heads, head_dim):
            return _cubin_bundles._compile_gated_delta_flat_prefill(
                num_k_heads=num_k_heads,
                num_v_heads=num_v_heads,
                head_dim=head_dim,
            )
        if variant_key == _flat_sm90_indexed_state_variant_key(
            num_k_heads, num_v_heads, head_dim
        ):
            return _cubin_bundles._compile_gated_delta_flat_prefill(
                num_k_heads=num_k_heads,
                num_v_heads=num_v_heads,
                head_dim=head_dim,
                indexed_bf16_state=True,
            )
    raise ValueError(f"unknown gated_delta flat SM90 variant {variant_key!r}")


def _compile_chunk_sm100_variant(variant_key: str):
    for num_k_heads, num_v_heads, head_dim in _SUPPORTED_RECURRENT_SHAPES:
        if variant_key == _chunk_sm100_indexed_state_variant_key(
            num_k_heads, num_v_heads, head_dim
        ):
            return _cubin_bundles._compile_gated_delta_chunk_sm100(
                num_k_heads=num_k_heads,
                num_v_heads=num_v_heads,
                head_dim=head_dim,
            )
    raise ValueError(f"unknown gated_delta chunk SM100 variant {variant_key!r}")


_aot_flat = AotFamily(
    "gated_delta",
    jit_compile_fn=_compile_flat_sm90_variant if _ENABLE_JIT else None,
)
_aot_sm100 = AotFamily(
    "gated_delta",
    jit_compile_fn=_compile_chunk_sm100_variant if _ENABLE_JIT else None,
)


def _normalize_x(x: torch.Tensor) -> torch.Tensor:
    if x.ndim == 3 and x.shape[-1] == 1:
        return x.squeeze(-1)
    if x.ndim == 2:
        return x
    raise ValueError(
        "causal_conv1d_update expects x with shape [B, D] or [B, D, 1], "
        f"got {tuple(x.shape)}"
    )


def _normalize_activation(activation: str | None) -> str | None:
    if activation in (None, "none", ""):
        return None
    if activation in ("silu", "swish"):
        return "silu"
    raise ValueError(f"unsupported causal_conv1d_update activation={activation!r}")


def _compile_variant(variant_key: str):
    for channels in _SUPPORTED_CONV_DIMS:
        conv_key = f"causal_conv1d_update_indexed_bf16_d{channels}_k{_CONV_KERNEL_SIZE}"
        if variant_key == conv_key:
            return _cubin_bundles._compile_gated_delta_causal_conv1d_update_indexed(
                channels=channels,
                kernel_size=_CONV_KERNEL_SIZE,
                num_threads=_THREADS,
            )
        packed_key = f"causal_conv1d_packed_state_bf16_d{channels}_k{_CONV_KERNEL_SIZE}"
        if variant_key == packed_key:
            return _cubin_bundles._compile_gated_delta_causal_conv1d_packed_state(
                channels=channels,
                kernel_size=_CONV_KERNEL_SIZE,
                channel_tile=_PACKED_CONV_CHANNEL_TILE,
                seq_tile=_PACKED_CONV_SEQ_TILE,
                num_threads=_PACKED_CONV_THREADS,
            )
    for num_k_heads, num_v_heads, head_dim in _SUPPORTED_RECURRENT_SHAPES:
        for capacity in _REPLAY_CAPACITIES:
            if variant_key == _replay_variant_key(num_k_heads, num_v_heads, head_dim, capacity):
                return _cubin_bundles._compile_gated_delta_replay_decode_indexed(
                    num_k_heads=num_k_heads,
                    num_v_heads=num_v_heads,
                    head_dim=head_dim,
                    replay_capacity=capacity,
                    num_threads=_REPLAY_DECODE_THREADS,
                )
            if variant_key == f"replay_decode_advance_indexed_c{capacity}":
                return _cubin_bundles._compile_gated_delta_replay_decode_advance_indexed(
                    replay_capacity=capacity,
                    num_threads=_REPLAY_ADVANCE_THREADS,
                )
        if variant_key == _recurrent_variant_key(
            "packed_prefill_prepare",
            num_k_heads,
            num_v_heads,
            head_dim,
        ):
            return _cubin_bundles._compile_gated_delta_packed_prefill_prepare(
                num_k_heads=num_k_heads,
                num_v_heads=num_v_heads,
                head_dim=head_dim,
                warps_per_block=_PREFILL_PREP_WARPS_PER_BLOCK,
            )
        if variant_key == _recurrent_variant_key(
            "packed_prefill_prepare_beta_fp32",
            num_k_heads,
            num_v_heads,
            head_dim,
        ):
            return _cubin_bundles._compile_gated_delta_packed_prefill_prepare(
                num_k_heads=num_k_heads,
                num_v_heads=num_v_heads,
                head_dim=head_dim,
                warps_per_block=_PREFILL_PREP_WARPS_PER_BLOCK,
                beta_fp32=True,
            )
        if variant_key == _recurrent_variant_key(
            "chunk_prefill_ampere",
            num_k_heads,
            num_v_heads,
            head_dim,
        ):
            return _cubin_bundles._compile_gated_delta_chunk_ampere(
                num_k_heads=num_k_heads,
                num_v_heads=num_v_heads,
                head_dim=head_dim,
            )
        if variant_key == _recurrent_variant_key(
            "chunk_prefill_ampere_indexed_state",
            num_k_heads,
            num_v_heads,
            head_dim,
        ):
            return _cubin_bundles._compile_gated_delta_chunk_ampere(
                num_k_heads=num_k_heads,
                num_v_heads=num_v_heads,
                head_dim=head_dim,
                indexed_bf16_state=True,
            )
        if variant_key == _recurrent_variant_key(
            "chunk_prefill_ampere_allocator_owned_indexed_state",
            num_k_heads,
            num_v_heads,
            head_dim,
        ):
            return _cubin_bundles._compile_gated_delta_chunk_ampere(
                num_k_heads=num_k_heads,
                num_v_heads=num_v_heads,
                head_dim=head_dim,
                indexed_bf16_state=True,
            )
    if variant_key.startswith("replay_decode_indexed_bf16_vh"):
        # key: replay_decode_indexed_bf16_vh{num_v_heads}_kh{num_k_heads}_d{D}_c{capacity}
        # Parse from the suffix after the fixed prefix to avoid the "_d" in
        # "decode" colliding with the head_dim "_d" field.
        suffix = variant_key[len("replay_decode_indexed_bf16_vh"):]
        vh = int(suffix.split("_kh")[0])
        kh = int(suffix.split("_kh")[1].split("_d")[0])
        d = int(suffix.split("_d")[1].split("_c")[0])
        cap = int(suffix.split("_c")[-1])
        return _cubin_bundles._compile_gated_delta_replay_decode_indexed(
            heads=vh,
            head_dim=d,
            num_k_heads=kh,
            replay_capacity=cap,
            num_threads=_REPLAY_DECODE_THREADS,
        )
    if variant_key.startswith("replay_decode_advance_indexed_c"):
        # Cursor-advance only depends on capacity; support any value (the
        # GQA path runs with replay capacities outside _REPLAY_CAPACITIES).
        cap = int(variant_key[len("replay_decode_advance_indexed_c"):])
        return _cubin_bundles._compile_gated_delta_replay_decode_advance_indexed(
            replay_capacity=cap,
            num_threads=_REPLAY_ADVANCE_THREADS,
        )
    if variant_key.startswith("replay_verify_indexed_bf16_vh"):
        # key: replay_verify_indexed_bf16_vh{num_v_heads}_kh{num_k_heads}_d{D}_c{capacity}_t{block_size}
        vh = int(variant_key.split("_vh")[1].split("_kh")[0])
        kh = int(variant_key.split("_kh")[1].split("_d")[0])
        d = int(variant_key.split("_d")[1].split("_c")[0])
        cap = int(variant_key.split("_c")[-1].split("_t")[0])
        bs = int(variant_key.split("_t")[-1])
        return _cubin_bundles._compile_gated_delta_replay_verify_indexed(
            heads=vh,
            head_dim=d,
            num_k_heads=kh,
            replay_capacity=cap,
            block_size=bs,
            num_threads=_REPLAY_DECODE_THREADS,
        )
    if variant_key.startswith("replay_materialize_seqrn_"):
        # key: replay_materialize_seqrn_{full|ckpt}_indexed_bf16_vh{num_v_heads}_d{D}_c{capacity}
        mode = variant_key.split("replay_materialize_seqrn_")[1].split("_indexed")[0]
        vh = int(variant_key.split("_vh")[1].split("_d")[0])
        d = int(variant_key.split("_d")[1].split("_c")[0])
        cap = int(variant_key.split("_c")[-1])
        return _cubin_bundles._compile_gated_delta_replay_materialize_indexed(
            heads=vh,
            head_dim=d,
            replay_capacity=cap,
            num_threads=_REPLAY_MATERIALIZE_THREADS,
            write_recurrent=(mode == "full"),
        )
    if variant_key == f"gated_rmsnorm_bf16_wbf16_d{_RECURRENT_HEAD_DIM}_eps1e-6":
        return _cubin_bundles._compile_gated_delta_gated_rmsnorm(
            hidden_size=_RECURRENT_HEAD_DIM,
            eps=1.0e-6,
            weight_dtype_name="bfloat16",
            warps_per_block=_GATED_RMSNORM_WARPS_PER_BLOCK,
        )
    if variant_key == f"gated_rmsnorm_bf16_wfp32_d{_RECURRENT_HEAD_DIM}_eps1e-6":
        return _cubin_bundles._compile_gated_delta_gated_rmsnorm(
            hidden_size=_RECURRENT_HEAD_DIM,
            eps=1.0e-6,
            weight_dtype_name="float32",
            warps_per_block=_GATED_RMSNORM_WARPS_PER_BLOCK,
        )
    raise ValueError(f"unknown gated_delta variant {variant_key!r}")


def _ensure_variant(variant_key: str, x: torch.Tensor) -> bool:
    device_index = int(x.device.index or 0)
    if (variant_key, device_index) in _family._handles:
        return True
    if _family.is_available(variant_key):
        return True
    if not _ENABLE_JIT:
        return False
    block_x = _THREADS
    if variant_key.startswith("causal_conv1d_packed_state_bf16_"):
        block_x = _PACKED_CONV_THREADS
    elif variant_key.startswith("chunk_prefill_ampere_"):
        block_x = 128
    elif variant_key.startswith("replay_materialize_seqrn_"):
        block_x = _REPLAY_MATERIALIZE_THREADS
    _cubin_bundles.jit_compile_and_install(
        family=_family,
        variant_key=variant_key,
        compile_fn=_compile_variant(variant_key),
        block_x=block_x,
        device_index=device_index,
    )
    return True


def _sm90_tensormap_workspace(device: torch.device) -> torch.Tensor:
    dev_idx = int(device.index or 0)
    stream_id = get_raw_stream(dev_idx)
    key = (dev_idx, stream_id)
    required = torch.cuda.get_device_properties(device).multi_processor_count * 128
    buf = _TENSORMAP_WORKSPACE_CACHE.get(key)
    if buf is None:
        buf = torch.empty((required,), device=device, dtype=torch.uint8)
        _TENSORMAP_WORKSPACE_CACHE[key] = buf
    elif buf.numel() < required:
        raise RuntimeError(
            f"gated_delta SM90 tensormap workspace overflow: need {required} bytes, "
            f"have {buf.numel()}"
        )
    return buf


def _flat_sm90_prefill_aot(
    query: torch.Tensor,
    key: torch.Tensor,
    value: torch.Tensor,
    g: torch.Tensor,
    beta: torch.Tensor,
    cu_seqlens: torch.Tensor,
    out: torch.Tensor,
    final_state: torch.Tensor,
    final_state_indices: torch.Tensor | None = None,
) -> bool:
    """Launch the AOT-emitted SM90 fully-fused chunked delta-rule prefill.

    Returns False if no AOT variant resolves for this arch (e.g. SM100),
    so the caller falls through to the Ampere chunked prefill path.
    The kernel reconstructs Q/K/V/O as transposed TMA views (D contiguous)
    matching the fake-tensor layouts in `_compile_gated_delta_flat_prefill`.
    """
    num_k_heads = int(query.shape[2])
    num_v_heads = int(value.shape[2])
    head_dim = int(query.shape[3])
    indexed_state = final_state_indices is not None
    variant_key = (
        _flat_sm90_indexed_state_variant_key(num_k_heads, num_v_heads, head_dim)
        if indexed_state
        else _flat_sm90_variant_key(num_k_heads, num_v_heads, head_dim)
    )
    bundle = _aot_flat.resolve(variant_key, get_cuda_arch())
    if bundle is None:
        return False

    device_index = int(query.device.index or 0)
    bundle.aot._ensure_device(device_index)

    seqlen = int(query.shape[1])
    num_sequences = int(cu_seqlens.numel() - 1)
    grid_x = num_sequences * num_v_heads
    qk_hd = num_k_heads * head_dim
    value_hd = num_v_heads * head_dim

    q_tma = torch.as_strided(
        query[0],
        (seqlen, head_dim, num_k_heads),
        (qk_hd, 1, head_dim),
    )
    k_tma = torch.as_strided(
        key[0],
        (head_dim, seqlen, num_k_heads),
        (1, qk_hd, head_dim),
    )
    v_tma = torch.as_strided(
        value[0],
        (head_dim, seqlen, num_v_heads),
        (1, value_hd, head_dim),
    )
    o_tma = torch.as_strided(
        out[0],
        (head_dim, seqlen, num_v_heads),
        (1, value_hd, head_dim),
    )
    workspace = _sm90_tensormap_workspace(query.device)

    tensors = [
        q_tma,
        k_tma,
        v_tma,
        o_tma,
        g.reshape(-1),
        beta.reshape(-1),
        final_state.reshape(-1),
    ]
    if final_state_indices is not None:
        tensors.append(final_state_indices)
    tensors.extend((workspace, cu_seqlens))
    if len(bundle.memref_specs) != len(tensors):
        raise RuntimeError(
            f"flat prefill memref count mismatch: ciface expects "
            f"{len(bundle.memref_specs)}, got {len(tensors)}"
        )
    structs = [spec.build(t) for t, spec in zip(tensors, bundle.memref_specs)]
    scalars = [
        ctypes.c_float(head_dim**-0.5),
        ctypes.c_int32(num_k_heads),  # num_q_heads
        ctypes.c_int32(num_k_heads),  # num_k_heads
        ctypes.c_int32(num_v_heads),  # num_v_heads
        ctypes.c_int32(num_v_heads),  # num_sab_heads
        ctypes.c_int32(num_sequences),
    ]
    if indexed_state:
        scalars.append(ctypes.c_int32(final_state.shape[0]))
    scalars.append(ctypes.c_int32(grid_x))
    stream = ctypes.c_void_p(get_raw_stream(device_index))
    bundle.invoke(structs, scalars, stream)
    return True


def _sm100_chunk_prefill_aot(
    query: torch.Tensor,
    key: torch.Tensor,
    value: torch.Tensor,
    g: torch.Tensor,
    beta: torch.Tensor,
    cu_seqlens: torch.Tensor,
    out: torch.Tensor,
    final_state: torch.Tensor,
    final_state_indices: torch.Tensor,
) -> bool:
    """Launch the SM100 TCGEN05 chunk kernel through its AOT host wrapper."""
    num_k_heads = int(query.shape[2])
    num_v_heads = int(value.shape[2])
    head_dim = int(query.shape[3])
    variant_key = _chunk_sm100_indexed_state_variant_key(
        num_k_heads,
        num_v_heads,
        head_dim,
    )
    bundle = _aot_sm100.resolve(variant_key, get_cuda_arch())
    if bundle is None:
        return False

    device_index = int(query.device.index or 0)
    bundle.aot._ensure_device(device_index)
    raw_stream = get_raw_stream(device_index)
    workspace_key = (device_index, raw_stream)
    num_sequences = int(cu_seqlens.numel() - 1)
    workspace_bytes = num_sequences * num_v_heads * 4 * 128
    workspace = _SM100_TENSORMAP_WORKSPACE_CACHE.get(workspace_key)
    if workspace is None or workspace.numel() < workspace_bytes:
        workspace = torch.empty(
            (workspace_bytes,),
            device=query.device,
            dtype=torch.int8,
        )
        _SM100_TENSORMAP_WORKSPACE_CACHE[workspace_key] = workspace

    tokens = int(query.shape[1])
    tensors = [
        query.view(tokens, num_k_heads, head_dim),
        key.view(tokens, num_k_heads, head_dim),
        value.view(tokens, num_v_heads, head_dim),
        g.view(tokens, num_v_heads),
        beta.view(tokens, num_v_heads),
        out.view(tokens, num_v_heads, head_dim),
        cu_seqlens,
        final_state,
        final_state_indices,
        workspace,
    ]
    bundle.invoke_state().invoke(
        tensors,
        raw_stream,
    )
    return True


def causal_conv1d_update_indexed(
    x: torch.Tensor,
    conv_state: torch.Tensor,
    weight: torch.Tensor,
    state_indices: torch.Tensor,
    bias: torch.Tensor | None = None,
    activation: str | None = "silu",
    *,
    out: torch.Tensor | None = None,
) -> torch.Tensor:
    """Update depthwise conv state rows selected by state_indices."""

    x2 = _normalize_x(x)
    if conv_state.ndim != 3:
        raise ValueError(f"conv_state must be [S, D, K], got {tuple(conv_state.shape)}")
    if weight.ndim != 2:
        raise ValueError(f"weight must be [D, K], got {tuple(weight.shape)}")
    if state_indices.ndim != 1 or state_indices.shape[0] != x2.shape[0]:
        raise ValueError(
            "state_indices must be [B] matching x batch dimension, got "
            f"{tuple(state_indices.shape)} for x={tuple(x2.shape)}"
        )
    if x2.shape[1] != conv_state.shape[1]:
        raise ValueError(
            f"x channels {x2.shape[1]} must match conv_state channels "
            f"{conv_state.shape[1]}"
        )
    if weight.shape != conv_state.shape[1:]:
        raise ValueError(
            f"weight shape {tuple(weight.shape)} must match conv_state "
            f"channel/kernel {tuple(conv_state.shape[1:])}"
        )
    act = _normalize_activation(activation)
    if out is None:
        out = torch.empty_like(x2)
    elif out.shape != x2.shape:
        raise ValueError(f"out shape must be {tuple(x2.shape)}, got {tuple(out.shape)}")

    channels = int(conv_state.shape[1])
    variant_key = f"causal_conv1d_update_indexed_bf16_d{channels}_k{_CONV_KERNEL_SIZE}"
    supported = (
        x2.is_cuda
        and x2.dtype == torch.bfloat16
        and conv_state.dtype == torch.bfloat16
        and weight.dtype == torch.bfloat16
        and out.dtype == torch.bfloat16
        and state_indices.is_cuda
        and state_indices.dtype == torch.int64
        and bias is None
        and act == "silu"
        and channels in _SUPPORTED_CONV_DIMS
        and conv_state.shape[2] == _CONV_KERNEL_SIZE
        and weight.shape == (channels, _CONV_KERNEL_SIZE)
        and _ensure_variant(variant_key, x2)
    )
    if supported:
        dispatch = _family.resolve_dispatch(
            out,
            variant_key=variant_key,
            grid_x=ceil_div(out.numel(), _THREADS),
        )
        dispatch(out, x2, conv_state, weight, state_indices)
        return out

    return warn_and_run_fallback(
        kernel_key="gated_delta_causal_conv1d_update_indexed",
        message=(
            "kestrel-kernels: no native gated_delta indexed causal_conv1d_update "
            f"variant for x={tuple(x2.shape)} dtype={x2.dtype}; using PyTorch fallback."
        ),
        fallback=causal_conv1d_update_indexed_torch,
        kwargs={
            "x": x2,
            "conv_state": conv_state,
            "weight": weight,
            "state_indices": state_indices,
            "bias": bias,
            "activation": activation,
            "out": out,
        },
    )


def causal_conv1d_packed(
    x: torch.Tensor,
    weight: torch.Tensor,
    seq_idx: torch.Tensor | None = None,
    bias: torch.Tensor | None = None,
    activation: str | None = "silu",
    *,
    final_state: torch.Tensor,
    out: torch.Tensor | None = None,
) -> torch.Tensor:
    """Run packed prefill depthwise causal convolution and write final states."""

    act = _normalize_activation(activation)
    if out is None:
        out = torch.empty_like(x)
    elif out.shape != x.shape:
        raise ValueError(f"out shape must be {tuple(x.shape)}, got {tuple(out.shape)}")

    channels = int(x.shape[1]) if x.ndim == 3 else 0
    variant_key = f"causal_conv1d_packed_state_bf16_d{channels}_k{_CONV_KERNEL_SIZE}"
    supported = (
        x.is_cuda
        and x.ndim == 3
        and x.shape[0] == 1
        and channels in _SUPPORTED_CONV_DIMS
        and x.dtype == torch.bfloat16
        and weight.shape == (channels, _CONV_KERNEL_SIZE)
        and weight.dtype == torch.bfloat16
        and seq_idx is not None
        and seq_idx.shape == (1, x.shape[2])
        and seq_idx.dtype == torch.int32
        and bias is None
        and act == "silu"
        and out.dtype == torch.bfloat16
        and final_state.is_cuda
        and final_state.dtype == torch.bfloat16
        and final_state.ndim == 3
        and final_state.shape[1:] == (channels, _CONV_KERNEL_SIZE)
        and final_state.is_contiguous()
        and _ensure_variant(variant_key, x)
    )
    if supported:
        dispatch = _family.resolve_dispatch(
            out,
            variant_key=variant_key,
            grid_x=ceil_div(
                channels,
                _PACKED_CONV_CHANNEL_TILE,
            )
            * ceil_div(
                x.shape[2],
                _PACKED_CONV_SEQ_TILE,
            ),
        )
        dispatch(out, x, weight, seq_idx, final_state)
        return out

    result = warn_and_run_fallback(
        kernel_key="gated_delta_causal_conv1d_packed",
        message=(
            "kestrel-kernels: no native gated_delta packed causal_conv1d "
            f"variant for x={tuple(x.shape)} dtype={x.dtype}; using PyTorch fallback."
        ),
        fallback=causal_conv1d_packed_torch,
        kwargs={
            "x": x,
            "weight": weight,
            "seq_idx": seq_idx,
            "bias": bias,
            "activation": activation,
            "final_state": final_state,
            "out": out,
        },
    )
    return result


def packed_recurrent_gated_delta_rule_decode_replay_indexed(
    mixed_qkv: torch.Tensor,
    a: torch.Tensor,
    b: torch.Tensor,
    A_log: torch.Tensor,
    dt_bias: torch.Tensor,
    checkpoint_state: torch.Tensor,
    replay_k: torch.Tensor,
    replay_u: torch.Tensor,
    replay_g: torch.Tensor,
    replay_lengths: torch.Tensor,
    state_indices: torch.Tensor,
    *,
    out: torch.Tensor | None = None,
) -> tuple[torch.Tensor, None]:
    """Run ReplaySSM-style GDN decode on state rows selected by state_indices."""

    if out is None:
        out = torch.empty(
            (
                mixed_qkv.shape[0],
                1,
                checkpoint_state.shape[1],
                checkpoint_state.shape[2],
            ),
            device=mixed_qkv.device,
            dtype=mixed_qkv.dtype,
        )
    capacity = int(replay_k.shape[1]) if replay_k.ndim == 4 else -1
    num_v_heads = int(checkpoint_state.shape[1]) if checkpoint_state.ndim == 4 else 0
    head_dim = int(checkpoint_state.shape[3]) if checkpoint_state.ndim == 4 else _RECURRENT_HEAD_DIM
    value_dim = int(checkpoint_state.shape[2]) if checkpoint_state.ndim == 4 else _RECURRENT_HEAD_DIM
    shape = (
        _infer_gqa_shape_from_mixed(int(mixed_qkv.shape[1]), num_v_heads, head_dim)
        if mixed_qkv.ndim == 2
        else None
    )
    num_k_heads = shape[0] if shape is not None else 0
    variant_key = (
        _replay_variant_key(num_k_heads, num_v_heads, head_dim, capacity)
        if shape is not None
        else ""
    )
    advance_variant_key = f"replay_decode_advance_indexed_c{capacity}"
    expected_replay_k = (
        checkpoint_state.shape[0],
        capacity,
        num_k_heads,
        head_dim,
    )
    expected_replay_v = (
        checkpoint_state.shape[0],
        capacity,
        num_v_heads,
        head_dim,
    )
    supported = (
        capacity in _REPLAY_CAPACITIES
        and mixed_qkv.is_cuda
        and mixed_qkv.ndim == 2
        and shape in _SUPPORTED_RECURRENT_SHAPES
        # SYMMETRIC heads only. The replay-key ring is allocated by VALUE head
        # (see qwen_compat._ensure_replay_state) and the compiled cubin's
        # ``replay_k`` ABI is now value-head-shaped (families/gated_delta.py
        # mReplayK uses ``v_heads``), so the GQA k!=v shape MUST go through the
        # value-head ``..._gqa`` dispatch. Were the generic path to claim the
        # k16/v32 shape, ``expected_replay_k`` below validates a key-head ring
        # (16) while the kernel indexes ``replay_k[..., head, :]`` by value head
        # (0..31) -> out-of-bounds / corrupted decode. ``num_k_heads ==
        # num_v_heads`` keeps this path for the symmetric variants only; the
        # runtime already routes k!=v to ``..._gqa`` (qwen_model.py decode_fn).
        and num_k_heads == num_v_heads
        and mixed_qkv.dtype == torch.bfloat16
        and a.shape == (mixed_qkv.shape[0], 1, num_v_heads)
        and b.shape == (mixed_qkv.shape[0], 1, num_v_heads)
        and a.dtype == torch.bfloat16
        and b.dtype == torch.bfloat16
        and A_log.shape == (num_v_heads,)
        and dt_bias.shape == (num_v_heads,)
        and A_log.dtype == torch.float32
        and dt_bias.dtype == torch.float32
        and checkpoint_state.ndim == 4
        and checkpoint_state.shape[1:] == (num_v_heads, head_dim, value_dim)
        and value_dim == head_dim
        and checkpoint_state.dtype == torch.float32
        and replay_k.shape == expected_replay_k
        and replay_k.dtype == torch.bfloat16
        and replay_u.shape == expected_replay_v
        and replay_u.dtype == torch.float32
        and replay_g.shape == expected_replay_v[:3]
        and replay_g.dtype == torch.float32
        and replay_lengths.shape == (checkpoint_state.shape[0],)
        and replay_lengths.dtype == torch.int32
        and state_indices.is_cuda
        and state_indices.dtype == torch.int64
        and state_indices.ndim == 1
        and state_indices.shape[0] == mixed_qkv.shape[0]
        and out.shape == (mixed_qkv.shape[0], 1, num_v_heads, head_dim)
        and out.dtype == torch.bfloat16
        and _ensure_variant(variant_key, mixed_qkv)
        and _ensure_variant(advance_variant_key, mixed_qkv)
    )
    if supported:
        dispatch = _family.resolve_dispatch(
            out,
            variant_key=variant_key,
            grid_x=(
                mixed_qkv.shape[0]
                * num_v_heads
                * ceil_div(head_dim, _REPLAY_DECODE_VALUE_TILE)
            ),
        )
        dispatch(
            out,
            mixed_qkv,
            a,
            b,
            A_log,
            dt_bias,
            checkpoint_state,
            replay_k,
            replay_u,
            replay_g,
            replay_lengths,
            state_indices,
        )
        # Cursor advance: a separate in-place kernel. Kept separate (not fused
        # into decode) because the decode grid has many blocks per state row
        # (heads x value-groups) that all read the cursor at entry — an in-place
        # fused write would race, and a ping-pong output buffer can't be swapped
        # under CUDA graph capture. In place + separate launch is graph-safe.
        advance = _family.resolve_dispatch(
            replay_lengths,
            variant_key=advance_variant_key,
            grid_x=ceil_div(state_indices.numel(), _REPLAY_ADVANCE_THREADS),
        )
        advance(replay_lengths, state_indices)
        return out, None

    return warn_and_run_fallback(
        kernel_key="gated_delta_replay_decode_indexed",
        message=(
            "kestrel-kernels: no native ReplaySSM gated_delta decode "
            f"variant for mixed_qkv={tuple(mixed_qkv.shape)} dtype={mixed_qkv.dtype}; "
            "using PyTorch fallback."
        ),
        fallback=packed_recurrent_gated_delta_rule_decode_replay_indexed_torch,
        kwargs={
            "mixed_qkv": mixed_qkv,
            "a": a,
            "b": b,
            "A_log": A_log,
            "dt_bias": dt_bias,
            "checkpoint_state": checkpoint_state,
            "replay_k": replay_k,
            "replay_u": replay_u,
            "replay_g": replay_g,
            "replay_lengths": replay_lengths,
            "state_indices": state_indices,
            "out": out,
        },
    )


def packed_recurrent_gated_delta_rule_decode_replay_indexed_gqa(
    mixed_qkv: torch.Tensor,
    a: torch.Tensor,
    b: torch.Tensor,
    A_log: torch.Tensor,
    dt_bias: torch.Tensor,
    checkpoint_state: torch.Tensor,
    replay_k: torch.Tensor,
    replay_u: torch.Tensor,
    replay_g: torch.Tensor,
    replay_lengths: torch.Tensor,
    state_indices: torch.Tensor,
    *,
    out: torch.Tensor | None = None,
) -> tuple[torch.Tensor, None]:
    """GQA single-token ReplaySSM GDN decode on rows selected by state_indices.

    Mirrors the symmetric decode but for the GQA shape where q/k have
    num_k_heads and v/state/gates have num_v_heads. mixed_qkv is
    [B, (2*num_k_heads + num_v_heads)*D] (post-conv q|k|v); out is [B,1,H,V].
    """
    B = mixed_qkv.shape[0]
    Dd = _RECURRENT_HEAD_DIM
    H = a.shape[2] if a.ndim == 3 else -1  # num_v_heads
    conv_dim = mixed_qkv.shape[1] if mixed_qkv.ndim == 2 else -1
    # GQA layout: conv_dim = 2*num_k_heads*Dd + num_v_heads*Dd  ->  num_k_heads
    KH = (conv_dim - H * Dd) // (2 * Dd) if (H > 0 and conv_dim > H * Dd) else -1
    if out is None:
        out = torch.empty(
            (B, 1, H, Dd), device=mixed_qkv.device, dtype=mixed_qkv.dtype
        )
    capacity = int(replay_k.shape[1]) if replay_k.ndim == 4 else -1
    variant_key = (
        f"replay_decode_indexed_bf16_vh{H}_kh{KH}_d{Dd}_c{capacity}"
    )
    advance_variant_key = f"replay_decode_advance_indexed_c{capacity}"
    expected_replay = (checkpoint_state.shape[0], capacity, H, Dd)
    supported = (
        capacity > 0
        and mixed_qkv.is_cuda
        and mixed_qkv.ndim == 2
        and KH > 0
        and H % KH == 0
        and conv_dim == (2 * KH + H) * Dd
        and mixed_qkv.dtype == torch.bfloat16
        and a.shape == (B, 1, H)
        and b.shape == (B, 1, H)
        and a.dtype == torch.bfloat16
        and b.dtype == torch.bfloat16
        and A_log.shape == (H,)
        and dt_bias.shape == (H,)
        and A_log.dtype == torch.float32
        and dt_bias.dtype == torch.float32
        and checkpoint_state.ndim == 4
        and checkpoint_state.shape[1:] == (H, Dd, Dd)
        and checkpoint_state.dtype == torch.float32
        and replay_k.shape == expected_replay
        and replay_k.dtype == torch.bfloat16
        and replay_u.shape == expected_replay
        and replay_u.dtype == torch.float32
        and replay_g.shape == expected_replay[:3]
        and replay_g.dtype == torch.float32
        and replay_lengths.shape == (checkpoint_state.shape[0],)
        and replay_lengths.dtype == torch.int32
        and state_indices.is_cuda
        and state_indices.dtype == torch.int64
        and state_indices.ndim == 1
        and state_indices.shape[0] == B
        and out.shape == (B, 1, H, Dd)
        and out.dtype == torch.bfloat16
        and _ensure_variant(variant_key, mixed_qkv)
        and _ensure_variant(advance_variant_key, mixed_qkv)
    )
    if supported:
        dispatch = _family.resolve_dispatch(
            out,
            variant_key=variant_key,
            grid_x=B * H * ceil_div(Dd, _REPLAY_DECODE_VALUE_TILE),
        )
        dispatch(
            out,
            mixed_qkv,
            a,
            b,
            A_log,
            dt_bias,
            checkpoint_state,
            replay_k,
            replay_u,
            replay_g,
            replay_lengths,
            state_indices,
        )
        # Cursor advance: separate in-place kernel (graph-safe), same as the
        # symmetric path. The advance only touches replay_lengths, so it is
        # head-shape independent and reuses the existing capacity-keyed variant.
        advance = _family.resolve_dispatch(
            replay_lengths,
            variant_key=advance_variant_key,
            grid_x=ceil_div(state_indices.numel(), _REPLAY_ADVANCE_THREADS),
        )
        advance(replay_lengths, state_indices)
        return out, None

    return warn_and_run_fallback(
        kernel_key="gated_delta_replay_decode_indexed",
        message=(
            "kestrel-kernels: no native GQA ReplaySSM gated_delta decode "
            f"variant for mixed_qkv={tuple(mixed_qkv.shape)} dtype={mixed_qkv.dtype}; "
            "using PyTorch fallback."
        ),
        fallback=packed_recurrent_gated_delta_rule_decode_replay_indexed_torch,
        kwargs={
            "mixed_qkv": mixed_qkv,
            "a": a,
            "b": b,
            "A_log": A_log,
            "dt_bias": dt_bias,
            "checkpoint_state": checkpoint_state,
            "replay_k": replay_k,
            "replay_u": replay_u,
            "replay_g": replay_g,
            "replay_lengths": replay_lengths,
            "state_indices": state_indices,
            "out": out,
        },
    )


def packed_recurrent_gated_delta_rule_verify_replay_indexed(
    mixed_qkv: torch.Tensor,
    a: torch.Tensor,
    b: torch.Tensor,
    A_log: torch.Tensor,
    dt_bias: torch.Tensor,
    checkpoint_state: torch.Tensor,
    replay_k: torch.Tensor,
    replay_u: torch.Tensor,
    replay_g: torch.Tensor,
    replay_lengths: torch.Tensor,
    state_indices: torch.Tensor,
    *,
    out: torch.Tensor | None = None,
) -> tuple[torch.Tensor, None]:
    """Multi-token ReplaySSM GDN block verify (Algorithm 4).

    Output-only over a T-token block from the committed checkpoint + ring buffer;
    appends the T block tokens' (k, u, g) to the ring buffer at [len .. len+T-1]
    but does NOT advance replay_lengths (the spec-loop commit sets the cursor to
    len + accepted). mixed_qkv is [B, T, 3*H*D] (post-conv q|k|v); out is [B, T, H, V].
    """
    B = mixed_qkv.shape[0]
    T = mixed_qkv.shape[1]
    Dd = _RECURRENT_HEAD_DIM
    H = a.shape[2] if a.ndim == 3 else _DEFAULT_VALUE_HEADS
    conv_dim = mixed_qkv.shape[2] if mixed_qkv.ndim == 3 else -1
    # GQA layout: conv_dim = 2*num_k_heads*Dd + num_v_heads*Dd  ->  num_k_heads
    KH = (conv_dim - H * Dd) // (2 * Dd) if (H > 0 and conv_dim > H * Dd) else -1
    if out is None:
        out = torch.empty((B, T, H, Dd), device=mixed_qkv.device, dtype=mixed_qkv.dtype)
    capacity = int(replay_k.shape[1]) if replay_k.ndim == 4 else -1
    variant_key = f"replay_verify_indexed_bf16_vh{H}_kh{KH}_d{Dd}_c{capacity}_t{T}"
    # The CuTe verify kernel indexes the replay ring as [S, capacity, H, D] by
    # VALUE head (mReplayK uses ``v_heads``), so a stale key-head ring or a
    # mismatched ``replay_u``/``replay_g`` capacity would read/write OUT OF
    # BOUNDS and corrupt replay state. Validate the same shapes the decode_gqa
    # and materialize gates check before dispatching native; on mismatch the
    # gate falls back to the torch reference (which rejects/handles it) exactly
    # like decode and materialize.
    expected_replay = (checkpoint_state.shape[0], capacity, H, Dd)
    supported = (
        mixed_qkv.is_cuda
        and mixed_qkv.ndim == 3
        and KH > 0
        and H % KH == 0
        and conv_dim == (2 * KH + H) * Dd
        and mixed_qkv.dtype == torch.bfloat16
        and a.shape == (B, T, H)
        and b.shape == (B, T, H)
        and a.dtype == torch.bfloat16
        and b.dtype == torch.bfloat16
        and A_log.shape == (H,)
        and dt_bias.shape == (H,)
        and A_log.dtype == torch.float32
        and dt_bias.dtype == torch.float32
        and checkpoint_state.ndim == 4
        and checkpoint_state.shape[1:] == (H, Dd, Dd)
        and checkpoint_state.dtype == torch.float32
        and replay_k.shape == expected_replay
        and replay_k.dtype == torch.bfloat16
        and replay_u.shape == expected_replay
        and replay_u.dtype == torch.float32
        and replay_g.shape == expected_replay[:3]
        and replay_g.dtype == torch.float32
        and replay_lengths.shape == (checkpoint_state.shape[0],)
        and replay_lengths.dtype == torch.int32
        and state_indices.is_cuda
        and state_indices.dtype == torch.int64
        and state_indices.shape[0] == B
        and out.shape == (B, T, H, Dd)
        and out.dtype == torch.bfloat16
        and _ensure_variant(variant_key, mixed_qkv)
    )
    if supported:
        dispatch = _family.resolve_dispatch(
            out,
            variant_key=variant_key,
            grid_x=B * H * ceil_div(Dd, _REPLAY_DECODE_VALUE_TILE),
        )
        dispatch(
            out, mixed_qkv, a, b, A_log, dt_bias, checkpoint_state,
            replay_k, replay_u, replay_g, replay_lengths, state_indices,
        )
        return out, None
    return warn_and_run_fallback(
        kernel_key="gated_delta_replay_verify_indexed",
        message=(
            "kestrel-kernels: no native ReplaySSM gated_delta verify "
            f"variant for mixed_qkv={tuple(mixed_qkv.shape)} dtype={mixed_qkv.dtype}; "
            "using PyTorch fallback."
        ),
        fallback=packed_recurrent_gated_delta_rule_verify_replay_indexed_torch,
        kwargs={
            "mixed_qkv": mixed_qkv, "a": a, "b": b, "A_log": A_log, "dt_bias": dt_bias,
            "checkpoint_state": checkpoint_state, "replay_k": replay_k, "replay_u": replay_u,
            "replay_g": replay_g, "replay_lengths": replay_lengths,
            "state_indices": state_indices, "out": out,
        },
    )


def materialize_replay_state_indexed(
    recurrent_state: torch.Tensor,
    checkpoint_state: torch.Tensor,
    replay_k: torch.Tensor,
    replay_u: torch.Tensor,
    replay_g: torch.Tensor,
    replay_lengths: torch.Tensor,
    state_indices: torch.Tensor,
    *,
    write_recurrent: bool = True,
) -> torch.Tensor:
    """Materialize selected ReplaySSM rows into recurrent/checkpoint states."""

    H = recurrent_state.shape[1] if recurrent_state.ndim == 4 else -1
    Dd = recurrent_state.shape[2] if recurrent_state.ndim == 4 else -1
    capacity = int(replay_k.shape[1]) if replay_k.ndim == 4 else -1
    mode = "full" if write_recurrent else "ckpt"
    variant_key = f"replay_materialize_seqrn_{mode}_indexed_bf16_vh{H}_d{Dd}_c{capacity}"
    expected_checkpoint = (
        recurrent_state.shape[0],
        H,
        recurrent_state.shape[3],
        Dd,
    ) if recurrent_state.ndim == 4 else ()
    supported = (
        recurrent_state.is_cuda
        and recurrent_state.ndim == 4
        and recurrent_state.dtype == torch.float32
        and Dd == recurrent_state.shape[3]
        and Dd == _RECURRENT_HEAD_DIM
        and H > 0
        and checkpoint_state.shape == expected_checkpoint
        and checkpoint_state.dtype == torch.float32
        and replay_k.shape == (recurrent_state.shape[0], capacity, H, Dd)
        and replay_k.dtype == torch.bfloat16
        and replay_u.shape == (recurrent_state.shape[0], capacity, H, Dd)
        and replay_u.dtype == torch.float32
        and replay_g.shape == (recurrent_state.shape[0], capacity, H)
        and replay_g.dtype == torch.float32
        and replay_lengths.shape == (recurrent_state.shape[0],)
        and replay_lengths.dtype == torch.int32
        and state_indices.is_cuda
        and state_indices.dtype == torch.int64
        and state_indices.ndim == 1
        and _ensure_variant(variant_key, recurrent_state)
    )
    if supported:
        dispatch = _family.resolve_dispatch(
            recurrent_state,
            variant_key=variant_key,
            grid_x=state_indices.numel() * H * ceil_div(Dd, _REPLAY_MATERIALIZE_VALUE_TILE),
        )
        dispatch(
            recurrent_state,
            checkpoint_state,
            replay_k,
            replay_u,
            replay_g,
            replay_lengths,
            state_indices,
        )
        return recurrent_state

    return warn_and_run_fallback(
        kernel_key="gated_delta_replay_materialize_indexed",
        message=(
            "kestrel-kernels: no native ReplaySSM gated_delta materialize "
            f"variant for recurrent_state={tuple(recurrent_state.shape)} "
            f"dtype={recurrent_state.dtype}; using PyTorch fallback."
        ),
        fallback=materialize_replay_state_indexed_torch,
        kwargs={
            "recurrent_state": recurrent_state,
            "checkpoint_state": checkpoint_state,
            "replay_k": replay_k,
            "replay_u": replay_u,
            "replay_g": replay_g,
            "replay_lengths": replay_lengths,
            "state_indices": state_indices,
            "write_recurrent": write_recurrent,
        },
    )


def packed_prefill_prepare(
    mixed_qkv: torch.Tensor,
    a: torch.Tensor,
    b: torch.Tensor,
    A_log: torch.Tensor,
    dt_bias: torch.Tensor,
    *,
    query: torch.Tensor | None = None,
    key: torch.Tensor | None = None,
    value: torch.Tensor | None = None,
    g: torch.Tensor | None = None,
    beta: torch.Tensor | None = None,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
    """Prepare Qwen packed prefill inputs for FLA chunk GDN."""

    if mixed_qkv.ndim != 3:
        raise ValueError(f"mixed_qkv must be [1, T, D], got {tuple(mixed_qkv.shape)}")
    seqlen = mixed_qkv.shape[1]
    num_v_heads = int(a.shape[2]) if a.ndim == 3 else _DEFAULT_VALUE_HEADS
    shape = _infer_gqa_shape_from_mixed(
        int(mixed_qkv.shape[2]),
        num_v_heads,
        _RECURRENT_HEAD_DIM,
    )
    num_k_heads, _, head_dim = (
        shape if shape is not None else (num_v_heads, num_v_heads, _RECURRENT_HEAD_DIM)
    )
    expected_query = (1, seqlen, num_k_heads, head_dim)
    expected_value = (1, seqlen, num_v_heads, head_dim)
    expected_3d = (1, seqlen, num_v_heads)
    if query is None:
        query = torch.empty(expected_query, device=mixed_qkv.device, dtype=mixed_qkv.dtype)
    if key is None:
        key = torch.empty(expected_query, device=mixed_qkv.device, dtype=mixed_qkv.dtype)
    if value is None:
        value = torch.empty(expected_value, device=mixed_qkv.device, dtype=mixed_qkv.dtype)
    if g is None:
        g = torch.empty(expected_3d, device=mixed_qkv.device, dtype=torch.float32)
    if beta is None:
        beta = torch.empty(expected_3d, device=mixed_qkv.device, dtype=mixed_qkv.dtype)

    prepare_op = (
        "packed_prefill_prepare_beta_fp32"
        if beta.dtype == torch.float32
        else "packed_prefill_prepare"
    )
    variant_key = (
        _recurrent_variant_key(prepare_op, num_k_heads, num_v_heads, head_dim)
        if shape is not None
        else ""
    )
    supported = (
        mixed_qkv.is_cuda
        and shape in _SUPPORTED_RECURRENT_SHAPES
        and mixed_qkv.dtype == torch.bfloat16
        and a.shape == expected_3d
        and b.shape == expected_3d
        and a.dtype == torch.bfloat16
        and b.dtype == torch.bfloat16
        and A_log.shape == (num_v_heads,)
        and dt_bias.shape == (num_v_heads,)
        and A_log.dtype == torch.float32
        and dt_bias.dtype == torch.float32
        and query.shape == expected_query
        and key.shape == expected_query
        and value.shape == expected_value
        and g.shape == expected_3d
        and beta.shape == expected_3d
        and query.dtype == torch.bfloat16
        and key.dtype == torch.bfloat16
        and value.dtype == torch.bfloat16
        and g.dtype == torch.float32
        and beta.dtype in (torch.bfloat16, torch.float32)
        and all(
            tensor.device == mixed_qkv.device
            for tensor in (a, b, A_log, dt_bias, query, key, value, g, beta)
        )
        and _packed_prefill_prepare_inputs_have_supported_layout(
            mixed_qkv,
            a,
            b,
            num_k_heads=num_k_heads,
            num_v_heads=num_v_heads,
            head_dim=head_dim,
        )
        and all(
            tensor.is_contiguous()
            for tensor in (
                A_log,
                dt_bias,
                query,
                key,
                value,
                g,
                beta,
            )
        )
        and _ensure_variant(variant_key, mixed_qkv)
    )
    if supported:
        dispatch = _family.resolve_dispatch(
            query,
            variant_key=variant_key,
            grid_x=ceil_div(
                seqlen * max(num_k_heads, num_v_heads),
                _PREFILL_PREP_WARPS_PER_BLOCK,
            ),
        )
        dispatch(query, key, value, g, beta, mixed_qkv, a, b, A_log, dt_bias)
        return query, key, value, g, beta

    return warn_and_run_fallback(
        kernel_key="gated_delta_packed_prefill_prepare",
        message=(
            "kestrel-kernels: no native gated_delta packed prefill prepare "
            f"variant for mixed_qkv={tuple(mixed_qkv.shape)} dtype={mixed_qkv.dtype}; "
            "using PyTorch fallback."
        ),
        fallback=packed_prefill_prepare_torch,
        kwargs={
            "mixed_qkv": mixed_qkv,
            "a": a,
            "b": b,
            "A_log": A_log,
            "dt_bias": dt_bias,
            "query": query,
            "key": key,
            "value": value,
            "g": g,
            "beta": beta,
        },
    )


def packed_gated_delta_rule_prefill(
    mixed_qkv: torch.Tensor,
    a: torch.Tensor,
    b: torch.Tensor,
    A_log: torch.Tensor,
    dt_bias: torch.Tensor,
    cu_seqlens: torch.Tensor,
    *,
    workspace: PackedGatedDeltaPrefillWorkspace | None = None,
    initial_state: torch.Tensor | None = None,
    output_final_state: bool = True,
    sequence_lengths: Sequence[int] | None = None,
    topology_token: PackedPrefillTopologyToken | None = None,
    out: torch.Tensor | None = None,
    final_state: torch.Tensor | None = None,
    final_state_indices: torch.Tensor | None = None,
    final_state_indices_allocator_owned: bool = False,
) -> tuple[torch.Tensor, torch.Tensor | None]:
    """Prepare and execute packed GDN prefill under one backend contract."""

    shape = (
        _infer_gqa_shape_from_mixed(int(mixed_qkv.shape[2]), int(a.shape[2]))
        if mixed_qkv.ndim == 3 and a.ndim == 3
        else None
    )
    if shape is None:
        raise ValueError(
            "cannot infer packed GDN prefill shape from "
            f"mixed_qkv={tuple(mixed_qkv.shape)} a={tuple(a.shape)}"
        )
    num_k_heads, num_v_heads, head_dim = shape
    tokens = int(mixed_qkv.shape[1])
    num_sequences = (
        int(cu_seqlens.numel() - 1) if cu_seqlens.ndim == 1 else 0
    )
    effective_cu_seqlens, topology_authority = (
        _resolve_packed_prefill_topology_offsets(
            topology_token,
            cu_seqlens,
            sequence_lengths,
            num_sequences=num_sequences,
            total_tokens=tokens,
        )
    )
    if workspace is None:
        workspace = _allocate_prefill_workspace(
            mixed_qkv,
            a,
            head_dim=head_dim,
        )
    if not workspace.can_serve(
        mixed_qkv,
        a,
        head_dim=head_dim,
    ):
        raise RuntimeError(
            "kestrel-kernels: packed GDN workspace cannot serve the current "
            "device/dtype/head geometry/token count"
        )
    active_workspace = workspace.for_tokens(tokens)
    if out is None:
        out = active_workspace.out
    elif (
        out.ndim != 4
        or out.shape[0] != 1
        or out.shape[1] < tokens
        or out.shape[2:] != (num_v_heads, head_dim)
        or out.device != mixed_qkv.device
        or out.dtype != mixed_qkv.dtype
        or not out.is_contiguous()
    ):
        raise ValueError(
            f"out must be contiguous [1,capacity>={tokens},{num_v_heads},{head_dim}] "
            f"on {mixed_qkv.device} with dtype={mixed_qkv.dtype}, got "
            f"shape={tuple(out.shape)} device={out.device} dtype={out.dtype}"
        )
    out = active_token_prefix(out, tokens)
    if final_state is None and output_final_state:
        if final_state_indices is not None:
            raise ValueError(
                "final_state_indices requires a caller-owned BF16 final_state pool"
            )
        final_state = torch.empty(
            (num_sequences, num_v_heads, head_dim, head_dim),
            device=mixed_qkv.device,
            dtype=torch.float32,
        )

    if not output_final_state:
        fallback_cu_seqlens = (
            effective_cu_seqlens
            if topology_authority is None
            else _prepare_packed_prefill_topology_launch(
                topology_authority,
                out,
            )
        )
        query, key, value, log_g, beta_bf16 = packed_prefill_prepare_torch(
            mixed_qkv,
            a,
            b,
            A_log,
            dt_bias,
            query=active_workspace.query,
            key=active_workspace.key,
            value=active_workspace.value,
            g=active_workspace.log_g,
            beta=active_workspace.beta_bf16,
        )
        return packed_recurrent_gated_delta_rule_prefill_torch(
            query,
            key,
            value,
            log_g,
            beta_bf16,
            fallback_cu_seqlens,
            initial_state=initial_state,
            output_final_state=False,
            out=out,
            final_state=None,
            final_state_indices=None,
        )

    sm100_indexed_state = (
        mixed_qkv.is_cuda
        and torch.cuda.get_device_capability(mixed_qkv.device)[0] == 10
        and final_state_indices is not None
        and final_state_indices_allocator_owned
        and final_state is not None
        and final_state.dtype == torch.bfloat16
        and active_workspace.beta_fp32 is not None
    )
    beta_buffer = (
        active_workspace.beta_fp32
        if sm100_indexed_state
        else active_workspace.beta_bf16
    )
    query, key, value, log_g, beta = packed_prefill_prepare(
        mixed_qkv,
        a,
        b,
        A_log,
        dt_bias,
        query=active_workspace.query,
        key=active_workspace.key,
        value=active_workspace.value,
        g=active_workspace.log_g,
        beta=beta_buffer,
    )
    return _packed_recurrent_gated_delta_rule_prefill_resolved(
        query,
        key,
        value,
        log_g,
        beta,
        effective_cu_seqlens,
        topology_authority=topology_authority,
        initial_state=initial_state,
        output_final_state=output_final_state,
        out=out,
        final_state=final_state,
        final_state_indices=final_state_indices,
        final_state_indices_allocator_owned=final_state_indices_allocator_owned,
    )


def packed_recurrent_gated_delta_rule_prefill(
    query: torch.Tensor,
    key: torch.Tensor,
    value: torch.Tensor,
    g: torch.Tensor,
    beta: torch.Tensor,
    cu_seqlens: torch.Tensor,
    *,
    initial_state: torch.Tensor | None = None,
    output_final_state: bool = True,
    use_qk_l2norm_in_kernel: bool = False,
    sequence_lengths: Sequence[int] | None = None,
    topology_token: PackedPrefillTopologyToken | None = None,
    out: torch.Tensor | None = None,
    final_state: torch.Tensor | None = None,
    final_state_indices: torch.Tensor | None = None,
    final_state_indices_allocator_owned: bool = False,
) -> tuple[torch.Tensor, torch.Tensor | None]:
    """Run the packed prefill recurrent GDN update for pre-normalized Qwen q/k.

    ``final_state_indices_allocator_owned`` is an internal fast-path contract
    for rows originating from the scheduler-owned page-table allocator. Other
    indexed calls retain the validating torch path.
    """

    if query.ndim != 4:
        raise ValueError(f"query must be [1, T, K, D], got {tuple(query.shape)}")
    seqlen = query.shape[1]
    num_sequences = cu_seqlens.numel() - 1 if cu_seqlens.ndim == 1 else 0
    effective_cu_seqlens, topology_authority = (
        _resolve_packed_prefill_topology_offsets(
            topology_token,
            cu_seqlens,
            sequence_lengths,
            num_sequences=num_sequences,
            total_tokens=seqlen,
        )
    )
    return _packed_recurrent_gated_delta_rule_prefill_resolved(
        query,
        key,
        value,
        g,
        beta,
        effective_cu_seqlens,
        topology_authority=topology_authority,
        initial_state=initial_state,
        output_final_state=output_final_state,
        use_qk_l2norm_in_kernel=use_qk_l2norm_in_kernel,
        out=out,
        final_state=final_state,
        final_state_indices=final_state_indices,
        final_state_indices_allocator_owned=final_state_indices_allocator_owned,
    )


def _packed_recurrent_gated_delta_rule_prefill_resolved(
    query: torch.Tensor,
    key: torch.Tensor,
    value: torch.Tensor,
    g: torch.Tensor,
    beta: torch.Tensor,
    effective_cu_seqlens: torch.Tensor,
    *,
    topology_authority: Any,
    initial_state: torch.Tensor | None = None,
    output_final_state: bool = True,
    use_qk_l2norm_in_kernel: bool = False,
    out: torch.Tensor | None = None,
    final_state: torch.Tensor | None = None,
    final_state_indices: torch.Tensor | None = None,
    final_state_indices_allocator_owned: bool = False,
) -> tuple[torch.Tensor, torch.Tensor | None]:
    """Execute recurrent prefill from one already-resolved topology snapshot."""

    if query.ndim != 4:
        raise ValueError(f"query must be [1, T, K, D], got {tuple(query.shape)}")
    seqlen = query.shape[1]
    num_sequences = (
        effective_cu_seqlens.numel() - 1
        if effective_cu_seqlens.ndim == 1
        else 0
    )
    num_k_heads = int(query.shape[2]) if query.ndim == 4 else 0
    num_v_heads = int(value.shape[2]) if value.ndim == 4 else 0
    head_dim = int(query.shape[3]) if query.ndim == 4 else _RECURRENT_HEAD_DIM
    value_dim = int(value.shape[3]) if value.ndim == 4 else head_dim
    shape = (num_k_heads, num_v_heads, head_dim)
    expected_query = (1, seqlen, num_k_heads, head_dim)
    expected_value = (1, seqlen, num_v_heads, head_dim)
    expected_3d = (1, seqlen, num_v_heads)
    expected_state = (num_sequences, num_v_heads, head_dim, head_dim)
    fallback_state = (
        num_sequences,
        num_v_heads,
        head_dim,
        value_dim,
    )
    if out is None:
        out = torch.empty(expected_value, device=query.device, dtype=query.dtype)
    if not output_final_state:
        fallback_cu_seqlens = (
            effective_cu_seqlens
            if topology_authority is None
            else _prepare_packed_prefill_topology_launch(
                topology_authority,
                out,
            )
        )
        return packed_recurrent_gated_delta_rule_prefill_torch(
            query,
            key,
            value,
            g,
            beta,
            fallback_cu_seqlens,
            initial_state=initial_state,
            output_final_state=False,
            use_qk_l2norm_in_kernel=use_qk_l2norm_in_kernel,
            out=out,
            final_state=None,
            final_state_indices=None,
        )
    if final_state_indices is not None and not final_state_indices_allocator_owned:
        fallback_cu_seqlens = (
            effective_cu_seqlens
            if topology_authority is None
            else _prepare_packed_prefill_topology_launch(
                topology_authority,
                out,
            )
        )
        return warn_and_run_fallback(
            kernel_key="gated_delta_packed_recurrent_prefill_indexed_state",
            message=(
                "kestrel-kernels: indexed packed recurrent prefill requires "
                "allocator-owned rows; using PyTorch fallback."
            ),
            fallback=packed_recurrent_gated_delta_rule_prefill_torch,
            kwargs={
                "query": query,
                "key": key,
                "value": value,
                "g": g,
                "beta": beta,
                "cu_seqlens": fallback_cu_seqlens,
                "initial_state": initial_state,
                "output_final_state": True,
                "use_qk_l2norm_in_kernel": use_qk_l2norm_in_kernel,
                "out": out,
                "final_state": final_state,
                "final_state_indices": final_state_indices,
            },
        )
    if final_state is None:
        final_state = torch.empty(
            fallback_state,
            device=query.device,
            dtype=torch.float32,
        )

    device_major = (
        torch.cuda.get_device_capability(query.device)[0]
        if query.is_cuda
        else 0
    )
    indexed_state_eligible = (
        final_state_indices is not None
        and final_state_indices_allocator_owned
        and final_state is not None
        and final_state.ndim == 4
        and final_state.shape[1:] == (num_v_heads, value_dim, head_dim)
        and final_state.dtype == torch.bfloat16
        and final_state.device == query.device
        and final_state.is_contiguous()
        and final_state_indices.shape == (num_sequences,)
        and final_state_indices.dtype == torch.int64
        and final_state_indices.device == query.device
        and final_state_indices.is_contiguous()
    )
    # SM100 TCGEN05/TMA chunked prefill. The older one-CTA-per-head Ampere
    # kernel remains the portable path for other architectures.
    sm100_eligible = (
        topology_authority is not None
        and device_major == 10
        and shape in _SUPPORTED_RECURRENT_SHAPES
        and value_dim == head_dim
        and query.shape == expected_query
        and key.shape == expected_query
        and value.shape == expected_value
        and query.dtype == torch.bfloat16
        and key.dtype == torch.bfloat16
        and value.dtype == torch.bfloat16
        and query.is_contiguous()
        and key.is_contiguous()
        and value.is_contiguous()
        and g.shape == expected_3d
        and beta.shape == expected_3d
        and g.dtype == torch.float32
        and beta.dtype == torch.float32
        and all(t.device == query.device for t in (key, value, g, beta))
        and g.is_contiguous()
        and beta.is_contiguous()
        and effective_cu_seqlens.device == query.device
        and effective_cu_seqlens.dtype == torch.int32
        and effective_cu_seqlens.ndim == 1
        and effective_cu_seqlens.is_contiguous()
        and out.shape == expected_value
        and out.dtype == torch.bfloat16
        and out.device == query.device
        and out.is_contiguous()
        and indexed_state_eligible
        and initial_state is None
        and not use_qk_l2norm_in_kernel
    )
    if sm100_eligible:
        launch_cu_seqlens = _prepare_packed_prefill_topology_launch(
            topology_authority,
            out,
        )
        if _sm100_chunk_prefill_aot(
            query,
            key,
            value,
            g,
            beta,
            launch_cu_seqlens,
            out,
            final_state,
            final_state_indices,
        ):
            return out, final_state if output_final_state else None

    # SM90 fully-fused chunked delta-rule prefill (AOT host wrapper). Far
    # cheaper than the serial recurrence below; the Ampere cubin is the
    # fallback for non-SM90 archs.
    flat_state_eligible = (
        final_state_indices is None
        and final_state is not None
        and final_state.shape == expected_state
        and final_state.dtype == torch.float32
        and final_state.device == query.device
        and final_state.is_contiguous()
    ) or indexed_state_eligible
    flat_eligible = (
        topology_authority is not None
        and query.is_cuda
        and torch.cuda.get_device_capability(query.device)[0] == 9
        and shape in _SUPPORTED_RECURRENT_SHAPES
        and value_dim == head_dim
        and query.shape == expected_query
        and key.shape == expected_query
        and value.shape == expected_value
        and query.dtype == torch.bfloat16
        and key.dtype == torch.bfloat16
        and value.dtype == torch.bfloat16
        and query.is_contiguous()
        and key.is_contiguous()
        and value.is_contiguous()
        and g.shape == expected_3d
        and beta.shape == expected_3d
        and g.dtype == torch.float32
        and beta.dtype == torch.bfloat16
        and all(
            tensor.device == query.device
            for tensor in (key, value, g, beta)
        )
        and g.is_contiguous()
        and beta.is_contiguous()
        and effective_cu_seqlens.device == query.device
        and effective_cu_seqlens.dtype == torch.int32
        and effective_cu_seqlens.ndim == 1
        and effective_cu_seqlens.is_contiguous()
        and out.shape == expected_value
        and out.dtype == torch.bfloat16
        and out.device == query.device
        and out.is_contiguous()
        and flat_state_eligible
        and initial_state is None
        and not use_qk_l2norm_in_kernel
    )
    if flat_eligible:
        launch_cu_seqlens = _prepare_packed_prefill_topology_launch(
            topology_authority,
            out,
        )
        if _flat_sm90_prefill_aot(
            query,
            key,
            value,
            g,
            beta,
            launch_cu_seqlens,
            out,
            final_state,
            final_state_indices,
        ):
            return out, final_state if output_final_state else None

    # Ampere-ISA chunked delta-rule prefill (cp.async + mma.sync). Ordinary
    # FP32 state is available on every non-SM90 arch. Allocator-owned BF16
    # indexed state has a portable SM8x variant and the existing SM100 variant.
    # One CTA per (sequence, value head); grid = sequences * value heads.
    chunk_variant_key = (
        _recurrent_variant_key("chunk_prefill_ampere", num_k_heads, num_v_heads, head_dim)
        if shape in _SUPPORTED_RECURRENT_SHAPES
        else ""
    )
    sm100_indexed_chunk_variant_key = (
        _recurrent_variant_key(
            "chunk_prefill_ampere_indexed_state",
            num_k_heads,
            num_v_heads,
            head_dim,
        )
        if shape in _SUPPORTED_RECURRENT_SHAPES
        else ""
    )
    indexed_chunk_variant_key = (
        _recurrent_variant_key(
            "chunk_prefill_ampere_allocator_owned_indexed_state",
            num_k_heads,
            num_v_heads,
            head_dim,
        )
        if shape in _SUPPORTED_RECURRENT_SHAPES
        else ""
    )
    chunked_common_eligible = (
        topology_authority is not None
        and query.is_cuda
        and num_sequences > 0
        # SM80+ (warp-MMA + BF16), excluding SM90 which takes the flat path above.
        and 8 <= device_major != 9
        and shape in _SUPPORTED_RECURRENT_SHAPES
        and value_dim == head_dim
        and query.shape == expected_query
        and key.shape == expected_query
        and value.shape == expected_value
        and query.dtype == torch.bfloat16
        and key.dtype == torch.bfloat16
        and value.dtype == torch.bfloat16
        and query.is_contiguous()
        and key.is_contiguous()
        and value.is_contiguous()
        and g.shape == expected_3d
        and beta.shape == expected_3d
        and g.dtype == torch.float32
        and beta.dtype == torch.bfloat16
        and all(
            tensor.device == query.device
            for tensor in (key, value, g, beta)
        )
        and g.is_contiguous()
        and beta.is_contiguous()
        and effective_cu_seqlens.device == query.device
        and effective_cu_seqlens.dtype == torch.int32
        and effective_cu_seqlens.ndim == 1
        and effective_cu_seqlens.is_contiguous()
        and out.shape == expected_value
        and out.dtype == torch.bfloat16
        and out.device == query.device
        and out.is_contiguous()
        and initial_state is None
        and not use_qk_l2norm_in_kernel
    )
    chunked_eligible = (
        chunked_common_eligible
        and final_state_indices is None
        and final_state is not None
        and final_state.shape == expected_state
        and final_state.dtype == torch.float32
        and final_state.device == query.device
        and final_state.is_contiguous()
        and _ensure_variant(chunk_variant_key, query)
    )
    if chunked_eligible:
        dispatch = _family.resolve_dispatch(
            out,
            variant_key=chunk_variant_key,
            grid_x=num_sequences * num_v_heads,
        )
        launch_cu_seqlens = _prepare_packed_prefill_topology_launch(
            topology_authority,
            out,
        )
        dispatch(out, query, key, value, g, beta, launch_cu_seqlens, final_state)
        return out, final_state if output_final_state else None

    sm100_indexed_chunked_eligible = (
        chunked_common_eligible
        and device_major == 10
        and indexed_state_eligible
        and _ensure_variant(sm100_indexed_chunk_variant_key, query)
    )
    if sm100_indexed_chunked_eligible:
        dispatch = _family.resolve_dispatch(
            out,
            variant_key=sm100_indexed_chunk_variant_key,
            grid_x=num_sequences * num_v_heads,
        )
        launch_cu_seqlens = _prepare_packed_prefill_topology_launch(
            topology_authority,
            out,
        )
        dispatch(
            out,
            query,
            key,
            value,
            g,
            beta,
            launch_cu_seqlens,
            final_state,
            final_state_indices,
        )
        return out, final_state if output_final_state else None

    indexed_chunked_contract = (
        chunked_common_eligible
        and device_major in (8, 12)
        and indexed_state_eligible
    )
    if indexed_chunked_contract:
        if not _ensure_variant(indexed_chunk_variant_key, query):
            raise RuntimeError(
                "native portable indexed BF16 GDN implementation is unavailable"
            )
        dispatch = _family.resolve_dispatch(
            out,
            variant_key=indexed_chunk_variant_key,
            grid_x=num_sequences * num_v_heads,
        )
        launch_cu_seqlens = _prepare_packed_prefill_topology_launch(
            topology_authority,
            out,
        )
        dispatch(
            out,
            query,
            key,
            value,
            g,
            beta,
            launch_cu_seqlens,
            final_state,
            final_state_indices,
        )
        return out, final_state if output_final_state else None

    fallback_cu_seqlens = (
        effective_cu_seqlens
        if topology_authority is None
        else _prepare_packed_prefill_topology_launch(
            topology_authority,
            out,
        )
    )
    return warn_and_run_fallback(
        kernel_key="gated_delta_packed_recurrent_prefill",
        message=(
            "kestrel-kernels: no native gated_delta packed recurrent prefill "
            f"variant for query={tuple(query.shape)} dtype={query.dtype}; "
            "using PyTorch fallback."
        ),
        fallback=packed_recurrent_gated_delta_rule_prefill_torch,
        kwargs={
            "query": query,
            "key": key,
            "value": value,
            "g": g,
            "beta": beta,
            "cu_seqlens": fallback_cu_seqlens,
            "initial_state": initial_state,
            "output_final_state": output_final_state,
            "use_qk_l2norm_in_kernel": use_qk_l2norm_in_kernel,
            "out": out,
            "final_state": final_state,
            "final_state_indices": final_state_indices,
        },
    )


def gated_rmsnorm(
    hidden_states: torch.Tensor,
    gate: torch.Tensor,
    weight: torch.Tensor,
    eps: float = 1e-6,
    *,
    out: torch.Tensor | None = None,
) -> torch.Tensor:
    """Run Qwen gated RMSNorm."""

    if gate is None:
        raise ValueError("gated_rmsnorm requires a gate tensor")
    if hidden_states.shape != gate.shape:
        raise ValueError(
            "hidden_states and gate must have the same shape, got "
            f"{tuple(hidden_states.shape)} and {tuple(gate.shape)}"
        )
    if hidden_states.ndim == 0:
        raise ValueError("hidden_states must have at least one dimension")
    if weight.shape != (hidden_states.shape[-1],):
        raise ValueError(
            f"weight shape must be {(hidden_states.shape[-1],)}, got {tuple(weight.shape)}"
        )
    if out is None:
        out = torch.empty_like(hidden_states)
    elif out.shape != hidden_states.shape:
        raise ValueError(
            f"out shape must be {tuple(hidden_states.shape)}, got {tuple(out.shape)}"
        )

    flat_hidden = hidden_states
    flat_gate = gate
    flat_out = out
    weight_dtype_name = {
        torch.bfloat16: "bf16",
        torch.float32: "fp32",
    }.get(weight.dtype)
    variant_key = f"gated_rmsnorm_bf16_w{weight_dtype_name}_d{_RECURRENT_HEAD_DIM}_eps1e-6"
    supported = (
        hidden_states.is_cuda
        and gate.is_cuda
        and weight.is_cuda
        and out.is_cuda
        and hidden_states.ndim == 2
        and hidden_states.dtype == torch.bfloat16
        and gate.dtype == torch.bfloat16
        and weight_dtype_name is not None
        and out.dtype == torch.bfloat16
        and hidden_states.shape[-1] == _RECURRENT_HEAD_DIM
        and abs(float(eps) - 1.0e-6) < 1.0e-12
        and gate.ndim == 2
        and out.ndim == 2
        and flat_hidden.shape == flat_gate.shape == flat_out.shape
        and flat_hidden.stride(-1) == 1
        and flat_gate.stride(-1) == 1
        and flat_out.stride(-1) == 1
        and _ensure_variant(variant_key, hidden_states)
    )
    if supported:
        dispatch = _family.resolve_dispatch(
            flat_out,
            variant_key=variant_key,
            grid_x=ceil_div(flat_hidden.shape[0], _GATED_RMSNORM_WARPS_PER_BLOCK),
        )
        dispatch(flat_out, flat_hidden, flat_gate, weight)
        return out

    return warn_and_run_fallback(
        kernel_key="gated_delta_gated_rmsnorm",
        message=(
            "kestrel-kernels: no native gated_delta gated_rmsnorm "
            f"variant for hidden_states={tuple(hidden_states.shape)} "
            f"dtype={hidden_states.dtype}; using PyTorch fallback."
        ),
        fallback=gated_rmsnorm_torch,
        kwargs={
            "hidden_states": hidden_states,
            "gate": gate,
            "weight": weight,
            "eps": eps,
            "out": out,
        },
    )


